import * as AasTypes from "../src/types";
import * as TestCommonJsonization from "./commonJsonization";

test("casts over an instance of Box", () => {
  const theBox =
    TestCommonJsonization.loadMinimalBox();

  expect(
    AasTypes.isItem(theBox)
  ).toStrictEqual(true);
  expect(
    AasTypes.asItem(theBox)
  ).toStrictEqual(theBox);

  expect(
    AasTypes.isBox(theBox)
  ).toStrictEqual(true);
  expect(
    AasTypes.asBox(theBox)
  ).toStrictEqual(theBox);
});

